#include <algorithm>
#include <cassert>
#include <cmath>
#include <iostream>
#include <stdexcept>
#ifdef NDEBUG
#error Tests require assertions enabled
#endif
// 1차원 카메라 교육 모델. 엔진/원작의 실제 공식이 아니다.
double target(double player, int direction) {
    if (!std::isfinite(player) || direction < -1 || direction > 1)
        throw std::invalid_argument("invalid state");
    // 화면 반폭 10, 월드 [0,100]: 중심은 [10,90].
    return std::max(10.0, std::min(90.0, player + 8.0 * direction));
}
double follow(double camera, double goal, double dt) {
    if (!std::isfinite(camera) || !std::isfinite(goal) ||
        !std::isfinite(dt) || dt < 0.0 || dt > 1.0)
        throw std::invalid_argument("invalid update");
    // 시간상수 0.2초. 고정 목표일 때 시간 분할과 독립적이다.
    const double alpha = -std::expm1(-dt / 0.2);
    return camera + (goal - camera) * alpha;
}
int main() {
    assert(target(50, 1) == 58);
    assert(target(50, -1) == 42);
    assert(target(1, -1) == 10);
    assert(target(99, 1) == 90);
    assert(follow(20, 60, 0) == 20);
    double sixty=20, thirty=20;
    for(int i=0;i<60;++i) sixty=follow(sixty,60,1.0/60);
    for(int i=0;i<30;++i) thirty=follow(thirty,60,1.0/30);
    assert(std::abs(sixty-thirty)<1e-10);
    assert(sixty>20 && sixty<60);
    double c=10;
    for(int i=0;i<10000;++i) {
        const double goal=target(i%101, (i%3)-1);
        c=follow(c,goal,1.0/60);
        assert(c>=10 && c<=90);
    }
    bool rejected=false;
    try { follow(20,60,-0.1); } catch(const std::invalid_argument&) { rejected=true; }
    assert(rejected);
    std::cout << "camera tests passed\n";
}
